Here's a complete example with both `DataRow` and `DynamicData` (ValueTuple) patterns:

**Production code** — `PriceCalculator.cs`:

```csharp
public class PriceCalculator
{
    public decimal CalculateTotal(decimal unitPrice, int quantity)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(unitPrice);
        ArgumentOutOfRangeException.ThrowIfNegative(quantity);
        return unitPrice * quantity;
    }

    public decimal ApplyDiscount(decimal price, int discountPercent)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(price);
        if (discountPercent < 0 || discountPercent > 100)
            throw new ArgumentOutOfRangeException(nameof(discountPercent));
        return price * (1 - discountPercent / 100m);
    }
}
```

**Tests** — `PriceCalculatorTests.cs`:

```csharp
[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // ── CalculateTotal: DataRow for simple inline values ──

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(10.00, 5, 50.00, DisplayName = "Multiple items")]
    [DataRow(0.00, 10, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.00, DisplayName = "Zero quantity")]
    [DataRow(0.01, 1, 0.01, DisplayName = "Smallest price")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1)]
    public void CalculateTotal_NegativePrice_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    [TestMethod]
    [DataRow(10.00, -1)]
    public void CalculateTotal_NegativeQuantity_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    // ── ApplyDiscount: DynamicData with ValueTuples for type-safe decimals ──

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)>
        DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (0m, 50, 0m),
        (199.99m, 20, 159.992m),
    ];

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData))]
    public void ApplyDiscount_InvalidDiscountPercent_Throws(
        decimal price, int discountPercent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }

    public static IEnumerable<(decimal price, int discountPercent)>
        InvalidDiscountData =>
    [
        (100m, -1),
        (100m, 101),
    ];

    [TestMethod]
    public void ApplyDiscount_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(-10m, 10));
    }
}
```

**Key patterns demonstrated:**

| Pattern | Where used | Why |
|---|---|---|
| `[DataRow]` | `CalculateTotal` tests | Best for simple inline constants (`double`/`int`/`string`) |
| `DynamicData` + ValueTuples | `ApplyDiscount` tests | Type-safe `decimal` values (DataRow can't hold `decimal` literals) |
| `Assert.ThrowsExactly<T>` | Negative tests | Modern replacement for `[ExpectedException]`; lets you inspect the exception |
| `Assert.AreEqual(expected, actual)` | All assertions | Expected first, actual second (avoids MSTEST0017) |
| `sealed` class | Test class | Performance and design clarity |
| Constructor init | `_calculator` | Enables `readonly`, works with nullability |
| `DisplayName` | DataRow attributes | Readable test names in Test Explorer |

**Project file** (if starting fresh):

```xml
<Project Sdk="MSTest.Sdk">
  <PropertyGroup>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
</Project>
```

With `MSTest.Sdk` version in `global.json`:

```json
{ "msbuild-sdks": { "MSTest.Sdk": "3.8.2" } }
```
